<script lang="ts">
	import Theme from "../components/Theme.svelte";
	import ImageUpload from "./ImageUpload.svelte";
	import type { Snippet } from "svelte";
	import StringOrSnippet from "../util/StringOrSnippet.svelte";

    /**
     * @description
     * A dual-theme logo upload component that provides side-by-side upload fields for
     * light and dark theme logos. Each side renders an `ImageUpload` within its
     * respective `Theme` wrapper so the preview matches the actual display context.
     *
     * @example
     * <LogoUpload
     *   lightLogoUploadUrl="/api/upload/logo-light"
     *   darkLogoUploadUrl="/api/upload/logo-dark"
     *   lightLogoSrc={org.logoLightUrl}
     *   darkLogoSrc={org.logoDarkUrl}
     * />
     */
    let {
        lightLogoInputName = 'logo_light_url',
        darkLogoInputName = 'logo_dark_url',
        lightLogoUploadUrl,
        darkLogoUploadUrl,
        buttonText = 'Select',
        lightLogoSrc,
        darkLogoSrc,
        lightHelp = 'This logo will be used on a light theme background.',
        darkHelp = 'If not set, the light theme logo will be used instead.',
        accept = 'image/png,image/jpg',
        maxSize = 1024 * 1024 * 4, // 4MB
        removable = true
    }: {
        lightLogoInputName?: string;
        darkLogoInputName?: string;
        lightLogoUploadUrl: string;
        darkLogoUploadUrl: string;
        buttonText?: string;
        lightLogoSrc?: string | null;
        darkLogoSrc?: string | null;
        lightHelp?: string | Snippet;
        darkHelp?: string | Snippet;
        accept: string;
        maxSize?: number;
        removable?: boolean;
    } = $props();

</script>

<div class="LogoUpload">
    <Theme theme="light">
        <div class="Content">
            <h5>Light theme</h5>
            <div class="Info">
                <small><StringOrSnippet content={lightHelp} /></small>
                <ImageUpload
                    compressMaxWidth={512}
                    compressSize={2}
                    {accept}
                    uploadUrl={lightLogoUploadUrl}
                    src={lightLogoSrc}
                    name={lightLogoInputName}
                    button={buttonText}
                    {removable}
                    {maxSize}
                />
            </div>
        </div>
    </Theme>
    <Theme theme="dark">
        <div class="Content">
            <h5>Dark theme</h5>
            <div class="Info">
                <small><StringOrSnippet content={darkHelp} /></small>
                <ImageUpload
                    compressMaxWidth={512}
                    compressSize={2}
                    {accept}
                    uploadUrl={darkLogoUploadUrl}
                    src={darkLogoSrc}
                    name={darkLogoInputName}
                    button={buttonText}
                    {removable}
                    {maxSize}
                />
            </div>
        </div>
    </Theme>
</div>

<style>
    .LogoUpload {
        border: var(--field-border);
        overflow: hidden;
        border-radius: var(--border-radius-base);
        margin: 0;
        padding: 0;
        list-style: none;
        display: grid;
        grid-template-columns: 1fr;
        container-type: inline-size;
    }
    .Content {
        background: var(--background-main);
    }
    .Info {
        padding: var(--space-md) var(--space-lg);
        display: grid;
        grid-template-columns: 1fr;
        gap: var(--space-md);
    }
    .Content :global(h5) {
        margin-block-end: 0;
        padding: var(--space-md);
    }
    .Content :global(.Rows) {
        padding: 0 var(--space-md) var(--space-md) var(--space-md);
    }
    @container (min-width: 500px) {
        .LogoUpload {
            grid-template-columns: 1fr 1fr;
        }
        .Content :global(h5) {
            margin-block-end: 0;
            padding: var(--space-md) var(--space-lg);
        }
    }
</style>